package model;
import java.time.LocalDate;
public class MedicalRecord { private int recordId,patientId,doctorId; private Integer appointmentId; private String diagnosis,symptoms,treatment,notes; private LocalDate recordDate; public int getRecordId(){return recordId;} public void setRecordId(int v){recordId=v;} public int getPatientId(){return patientId;} public void setPatientId(int v){patientId=v;} public int getDoctorId(){return doctorId;} public void setDoctorId(int v){doctorId=v;} public Integer getAppointmentId(){return appointmentId;} public void setAppointmentId(Integer v){appointmentId=v;} public String getDiagnosis(){return diagnosis;} public void setDiagnosis(String v){diagnosis=v;} public String getSymptoms(){return symptoms;} public void setSymptoms(String v){symptoms=v;} public String getTreatment(){return treatment;} public void setTreatment(String v){treatment=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public LocalDate getRecordDate(){return recordDate;} public void setRecordDate(LocalDate v){recordDate=v;} }
